// Warm Keys Voicer: Suno Studio audio effect for the KEYS stem (applied to rendered audio, not a lyric tag).
// Signal chain, in order:
//   1. Input trim: convert 'input gain' dB to linear and scale each channel.
//   2. Attack soften: g.asymmetricOnePole tracks g.abs(trimmed) as an envelope (fixed slow attack, fast release
//      coefs derived from time constants and config.sampleRate via coef = clamp(1 - 1/(seconds*sr), 0, 0.9999)
//      as in de-esser). The signal is scaled by (env / (env + eps)) to approximate a transient-rounded version,
//      then blended toward it by 'attack soften' percent to round hard note onsets.
//   3. Warm tilt EQ: lowshelf +tilt near 250Hz and highshelf -tilt near 5kHz (opposite via g.mul by -1),
//      driven by one 'warmth/tilt' param.
//   4. Saturation: scale by 'saturation' (dB via g.dbToLin) then g.tanh for gentle harmonic warmth.
//   5. Air: g.biquad highshelf near 10kHz driven by 'air' dB.
//   6. Dry/wet: g.lerp between trimmed dry and processed by 'dry/wet mix'.
//   7. Output gain, bypass select via g.lerp, then g.tanh safety before g.output.
// Bypass: g.lerp(bypass, out, trimmed) ASSUMES the 'bypass' enum resolves to 0 ('off') / 1 ('on'), so
// 'off' passes the PROCESSED signal and 'on' passes the DRY signal (see AUTHORING.md).
// ASSUMPTION: the shelf g.biquad stages pass a 'gainDb' field not confirmed from the one example (see AUTHORING.md).
function build(g, config) {
  var inL = g.input('audioInL');
  var inR = g.input('audioInR');

  var inGainDb = g.input('input gain');
  var tiltDb = g.input('warmth/tilt');
  var softenPct = g.input('attack soften');
  var satDb = g.input('saturation');
  var airDb = g.input('air');
  var mixPct = g.input('dry/wet mix');
  var outGainDb = g.input('output gain');
  var bypass = g.input('bypass');

  var inGain = g.dbToLin(inGainDb);
  var outGain = g.dbToLin(outGainDb);
  var satLin = g.dbToLin(satDb);
  var mix = g.clamp(g.div(mixPct, g.constant(100)), g.zero(), g.constant(1));
  var soften = g.clamp(g.div(softenPct, g.constant(100)), g.zero(), g.constant(1));
  var negTilt = g.mul(tiltDb, g.constant(-1));
  var sr = g.constant(config.sampleRate);

  // one-pole coef approximation: coef = clamp(1 - 1/(seconds*sr), 0, 0.9999) (slow 30ms attack, fast 8ms release).
  var attackSamples = g.max(g.mul(g.constant(0.03), sr), g.constant(1));
  var releaseSamples = g.max(g.mul(g.constant(0.008), sr), g.constant(1));
  var attackCoef = g.clamp(g.sub(g.constant(1), g.div(g.constant(1), attackSamples)), g.zero(), g.constant(0.9999));
  var releaseCoef = g.clamp(g.sub(g.constant(1), g.div(g.constant(1), releaseSamples)), g.zero(), g.constant(0.9999));

  function chain(x) {
    var trimmed = g.mul(x, inGain);
    var env = g.asymmetricOnePole({ target: g.abs(trimmed), attackCoef: attackCoef, releaseCoef: releaseCoef });
    var inst = g.max(g.abs(trimmed), g.constant(0.000001));
    var softGain = g.clamp(g.div(env, inst), g.zero(), g.constant(1));
    var softened = g.lerp(soften, trimmed, g.mul(trimmed, softGain));
    var low = g.biquad({ input: softened, cutoff: g.constant(250), resonance: g.constant(0.707), mode: 'lowshelf', gainDb: tiltDb });
    var tilted = g.biquad({ input: low, cutoff: g.constant(5000), resonance: g.constant(0.707), mode: 'highshelf', gainDb: negTilt });
    var sat = g.tanh(g.mul(tilted, satLin));
    var air = g.biquad({ input: sat, cutoff: g.constant(10000), resonance: g.constant(0.707), mode: 'highshelf', gainDb: airDb });
    var wet = g.lerp(mix, trimmed, air);
    var out = g.mul(wet, outGain);
    var active = g.lerp(bypass, out, trimmed);
    return g.tanh(active);
  }

  g.output('audioOutL', chain(inL));
  g.output('audioOutR', chain(inR));
}
